import './style.css';
import {Team,PlayerCard,MatchState,MatchDifficulty,Rarity,createTeam,autoFillRoster,teamPower,goaliePower,generateAiTeam,createMatchState,playMatchShift,awardHomeMatch,applyEquipment,equipmentCatalog} from './game';
type HeroRole='LW'|'C'|'RW'|'LD'|'RD'|'G';
type HeroProfile={role:HeroRole;name:string;level:number;xp:number;skillPoints?:number;stats:{speed:number;agility:number;strength:number;stamina:number;reaction:number};gear:string[];trophies:string[]};
type Screen='office'|'team'|'cards'|'match'|'wardrobe'|'club'|'stadium'|'playoff'|'standings'|'settings'|'picker'|'player'|'heroSetup'|'heroRoom';
type SlotRef={kind:'line';line:number;field:'center'|'leftWing'|'rightWing'|'defense1'|'defense2'}|{kind:'goalie';number:1|2};
const KEY='hockey-manager-web-save-v2';
const HERO_KEY='hockey-puckit-hero-v1';
const loadHero=():HeroProfile|null=>{try{const raw=localStorage.getItem(HERO_KEY);return raw?JSON.parse(raw) as HeroProfile:null;}catch{return null;}};
const saveHero=(profile:HeroProfile)=>localStorage.setItem(HERO_KEY,JSON.stringify(profile));
const heroRoleNames:Record<HeroRole,string>={LW:'ЛЕВЫЙ НАПАДАЮЩИЙ',C:'ЦЕНТРАЛЬНЫЙ НАПАДАЮЩИЙ',RW:'ПРАВЫЙ НАПАДАЮЩИЙ',LD:'ЛЕВЫЙ ЗАЩИТНИК',RD:'ПРАВЫЙ ЗАЩИТНИК',G:'ГОЛКИПЕР'};
const heroRoleShort:Record<HeroRole,string>={LW:'ЛН',C:'Ц',RW:'ПН',LD:'ЛЗ',RD:'ПЗ',G:'ГК'};
const heroGearSlots=(role:HeroRole)=>role==='G'?['Шлем вратаря','Щитки','Ловушка','Блокер','Клюшка вратаря','Нагрудник','Коньки']:['Шлем','Нагрудник','Перчатки','Клюшка','Коньки','Джерси','Шорты'];
const makeHero=(role:HeroRole,name:string):HeroProfile=>({role,name:name.trim()||'Новичок',level:1,xp:0,skillPoints:5,stats:role==='G'?{speed:48,agility:66,strength:70,stamina:68,reaction:76}:{speed:role==='LD'||role==='RD'?64:72,agility:role==='C'?76:69,strength:role==='LD'||role==='RD'?74:62,stamina:70,reaction:42},gear:heroGearSlots(role).map((x,i)=>i===0?'Стартовый комплект':i===3?(role==='G'?'Клюшка вратаря «Старт»':'Клюшка «Старт»'):'Базовый комплект'),trophies:[]});
const load=():Team=>{try{const s=localStorage.getItem(KEY);if(s)return JSON.parse(s) as Team;}catch{}return createTeam();};
let team=load(),hero=loadHero(),screen:Screen=loadHero()?'office':'heroSetup',slot:SlotRef|null=null,selectedId:string|null=null,difficulty:MatchDifficulty='MEDIUM',opponent:Team|null=null,matchHome:Team|null=null,match:MatchState|null=null,autoTimer:number|undefined,eventFocusTimer:number|undefined,matchEventFocus:'home'|'away'='home',notice='';
type LiveRuntime={players:{x:number;y:number}[];puckX:number;puckY:number;owner:'home'|'away';carrier:number;phase:'play'|'shot'|'rebound'|'stoppage';paused:boolean;elapsed:number;shiftElapsed:number;actionTimer:number;shotElapsed:number;shotFrom:{x:number;y:number};shotTo:{x:number;y:number};shotSide:'home'|'away';faceoff:boolean;faceoffTimer:number;lastFrame:number;breakoutTimer:number;};
let liveRuntime:LiveRuntime|null=null,liveFrame:number|undefined;
const save=()=>localStorage.setItem(KEY,JSON.stringify(team));
const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const money=(n:number)=>n.toLocaleString('ru-RU');
const rarity=(r:Rarity)=>({COMMON:'ОБЫЧНАЯ',RARE:'РЕДКАЯ',EPIC:'ЭПИЧЕСКАЯ',LEGENDARY:'ЛЕГЕНДАРНАЯ'}[r]);
const color=(r:Rarity)=>({COMMON:'#8da3b8',RARE:'#42b8ee',EPIC:'#a47aff',LEGENDARY:'#f5bd4f'}[r]);
const $=<T extends HTMLElement>(q:string)=>document.querySelector<T>(q);
function toast(s:string){notice=s;render();window.setTimeout(()=>{notice='';render();},2500);}
function header(t:string,back=true){const avatar=hero?'<button class="crest hero-header-avatar" data-screen="heroRoom" aria-label="Открыть комнату героя"><span>'+(hero.role==='G'?'🧤':'🏒')+'</span><small>'+heroRoleShort[hero.role]+'</small></button>':'<div class="crest">🏒</div>';return '<header class="top"><div class="brand">'+(back?'<button class="back" data-action="back">←</button>':'')+avatar+'<div><div class="eyebrow">HOCKEY: PUCK IT!</div><h1>'+t+'</h1></div></div><span class="live">WEB PLAYTEST</span></header>';}
function playerCard(p:PlayerCard,small=false){return '<article class="player-card rarity-'+p.rarity.toLowerCase()+(small?' compact':'')+'"><div class="player-card-top"><small style="color:'+color(p.rarity)+'">'+rarity(p.rarity)+'</small><b>'+(p.isGoalie?'🥅':'🏒')+'</b></div><div class="player-avatar">'+(p.isGoalie?'🧤':'🏒')+'</div><strong>'+esc(p.name)+'</strong><div class="stats-grid">'+(p.isGoalie?'<span>РЕАКЦИЯ <b>'+(p.reaction/10).toFixed(1)+'</b></span>':'<span>СКОРОСТЬ <b>'+(p.speed/10).toFixed(1)+'</b></span>')+'<span>ЛОВКОСТЬ <b>'+p.agility+'</b></span><span>СИЛА <b>'+p.strength+'</b></span><span>ВЫНОСЛИВОСТЬ <b>'+p.stamina+'</b></span></div></article>';}
function tile(icon:string,title:string,sub:string,to:Screen,c:string){return '<button class="menu-tile" data-screen="'+to+'" style="--tile:'+c+'"><span>'+icon+'</span><b>'+title+'</b><small>'+sub+'</small></button>';}
function office(){return header('Главный офис',false)+'<section class="home-hero"><div class="arena-lights"></div><div class="hero-copy"><div class="hero-kicker"><i></i> YOUR CLUB · YOUR LEGACY</div><div class="hero-brand">HOCKEY<span>:</span><br><strong>PUCK IT!</strong></div><p class="hero-tagline">ТВОЙ ЛЁД. ТВОИ ПРАВИЛА.</p><div class="hero-club"><span class="hero-crest">'+esc(team.club.logo)+'</span><span><small>ТВОЯ КОМАНДА</small><b>'+esc(team.club.displayName)+'</b></span><span class="hero-rating"><small>POWER</small><b>'+teamPower(team).toFixed(1)+'</b></span></div><button class="hero-play" data-screen="match"><span class="play-icon">▶</span><span><small>СЛЕДУЮЩИЙ МАТЧ</small><b>ВЫЙТИ НА ЛЁД</b></span><strong>→</strong></button></div><div class="hero-ice"><div class="ice-ring ring-one"></div><div class="ice-ring ring-two"></div><div class="ice-player-silhouette">🏒</div><div class="ice-puck"></div><span class="hero-side-label">EST. 2026　·　PLAY HARD</span></div><div class="hero-bottom-line"><span>BUILT FOR THE LOVE OF THE GAME</span><span>01 / CLUB HQ</span></div></section><section class="home-economy"><div class="home-stat"><span class="stat-icon">＄</span><span><small>БЮДЖЕТ КЛУБА</small><b>'+money(team.economy.dollars)+'</b></span><em>↗</em></div><div class="home-stat gold"><span class="stat-icon">✦</span><span><small>ЗОЛОТЫЕ ШАЙБЫ</small><b>'+team.economy.goldPucks+'</b></span><em>✧</em></div></section><div class="home-section-head"><span><small>THE FRONT OFFICE</small><b>УПРАВЛЕНИЕ КЛУБОМ</b></span><i>ВЫБЕРИ СВОЙ ПУТЬ</i></div><section class="home-menu-grid"><button class="home-menu-card roster" data-screen="team"><span class="home-menu-number">01</span><span class="home-menu-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><g><g><circle cx="24" cy="7.5" r="3.2"/><path d="M18.5 19.5v-3.2c0-3.1 2.2-5.2 5.5-5.2s5.5 2.1 5.5 5.2v3.2z"/></g><g><circle cx="9" cy="17" r="2.8"/><path d="M4.2 28v-2.5c0-2.8 1.9-4.7 4.8-4.7s4.8 1.9 4.8 4.7V28z"/></g><g><circle cx="39" cy="17" r="2.8"/><path d="M34.2 28v-2.5c0-2.8 1.9-4.7 4.8-4.7s4.8 1.9 4.8 4.7V28z"/></g><g><circle cx="17" cy="30" r="2.6"/><path d="M12.5 40v-2.2c0-2.6 1.8-4.3 4.5-4.3s4.5 1.7 4.5 4.3V40z"/></g><g><circle cx="31" cy="30" r="2.6"/><path d="M26.5 40v-2.2c0-2.6 1.8-4.3 4.5-4.3s4.5 1.7 4.5 4.3V40z"/></g></g></svg></span><b>СОСТАВ</b><small>Звенья и игроки</small><i>→</i></button><button class="home-menu-card collection" data-screen="cards"><span class="home-menu-number">02</span><span class="home-menu-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><g><rect x="5.5" y="13" width="21" height="29" rx="3" transform="rotate(-12 16 27.5)"/><rect x="14" y="7" width="21" height="31" rx="3"/><rect x="23" y="12" width="19" height="28" rx="3" transform="rotate(10 32.5 26)"/><path d="M19 13h11M19 18h11M19 23h7M29 19h8M29 24h8M29 29h6"/></g></svg></span><b>КОЛЛЕКЦИЯ</b><small>'+team.allCards.length+' карточек игроков</small><i>→</i></button><button class="home-menu-card wardrobe" data-screen="wardrobe"><span class="home-menu-number">03</span><span class="home-menu-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M24 5l5 10 11 2-8 8 2 12-10-6-10 6 2-12-8-8 11-2z"/><path d="M24 14v16M16 22h16"/></svg></span><b>ЭКИПИРОВКА</b><small>Стиль и усиления</small><i>→</i></button><button class="home-menu-card tournament" data-screen="playoff"><span class="home-menu-number">04</span><span class="home-menu-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M14 7h20v8c0 9-4 14-10 14S14 24 14 15zM14 11H7v5c0 6 4 9 10 9M34 11h7v5c0 6-4 9-10 9M24 29v8M17 41h14M19 37h10"/></svg></span><b>ТУРНИР</b><small>Путь к чемпионству</small><i>→</i></button><button class="home-menu-card club" data-screen="club"><span class="home-menu-number">05</span><span class="home-menu-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M24 5l16 7v11c0 10-7 16-16 20C15 39 8 33 8 23V12z"/><path d="M16 19l8-5 8 5v10l-8 5-8-5z"/></svg></span><b>МОЙ КЛУБ</b><small>Имя и эмблема</small><i>→</i></button><button class="home-menu-card arena" data-screen="stadium"><span class="home-menu-number">06</span><span class="home-menu-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><rect x="7" y="6" width="34" height="36" rx="9"/><path d="M7 17h34M7 31h34M24 6v36"/><circle cx="24" cy="24" r="5"/></svg></span><b>АРЕНА</b><small>Твой домашний лёд</small><i>→</i></button></section><section class="home-footer"><button data-screen="standings">ТУРНИРНАЯ ТАБЛИЦА ↗</button><button data-screen="settings">⚙ НАСТРОЙКИ</button><span>HOCKEY: PUCK IT! <i>—</i> WEB PLAYTEST</span></section>';}
function slotButton(p:PlayerCard|null,s:SlotRef,label:string){return '<button class="roster-slot '+(p?'filled':'')+'" data-slot="'+encodeURIComponent(JSON.stringify(s))+'"><small>'+label+'</small><b>'+(p?esc(p.name):'＋ Выбрать игрока')+'</b><span>'+(p?rarity(p.rarity):'Пустой слот')+'</span></button>';}
function teamPage(){let html=header('Состав команды')+'<section class="panel"><div class="panel-title">СОСТАВ ИГРОКОВ</div><p>Собери четыре звена и выбери двух вратарей. Один игрок — один слот.</p><button class="primary" data-action="autofill">🎲 Авторасстановка</button><button class="secondary" data-screen="cards">📋 Все карточки ('+team.allCards.length+')</button></section>';team.lines.forEach((l,i)=>{html+='<section class="panel roster-line"><div class="line-heading"><b>ЗВЕНО '+(i+1)+'</b></div><div class="roster-slots">'+slotButton(l.leftWing,{kind:'line',line:i,field:'leftWing'},'ЛЕВЫЙ')+slotButton(l.center,{kind:'line',line:i,field:'center'},'ЦЕНТР')+slotButton(l.rightWing,{kind:'line',line:i,field:'rightWing'},'ПРАВЫЙ')+'</div><div class="roster-slots defenders">'+slotButton(l.defense1,{kind:'line',line:i,field:'defense1'},'ЗАЩИТНИК 1')+slotButton(l.defense2,{kind:'line',line:i,field:'defense2'},'ЗАЩИТНИК 2')+'</div></section>';});return html+'<section class="panel"><div class="line-heading"><b>🧤 ВРАТАРИ</b></div><div class="roster-slots">'+slotButton(team.goalie1,{kind:'goalie',number:1},'ВРАТАРЬ №1')+slotButton(team.goalie2,{kind:'goalie',number:2},'ВРАТАРЬ №2')+'</div></section>';}
function pickerPage(){if(!slot)return '';let current=slot.kind==='goalie'?(slot.number===1?team.goalie1:team.goalie2):team.lines[slot.line][slot.field];let used=new Set<string>();team.lines.forEach(l=>[l.center,l.leftWing,l.rightWing,l.defense1,l.defense2].forEach(p=>{if(p&&p.id!==current?.id)used.add(p.id);}));[team.goalie1,team.goalie2].forEach(p=>{if(p&&p.id!==current?.id)used.add(p.id);});let choices=team.allCards.filter(p=>p.isGoalie===(slot!.kind==='goalie')&&!used.has(p.id));return header('Выбор игрока')+'<section class="panel"><p>Выбери свободную карточку для этого места.</p>'+(current?'<button class="secondary" data-action="remove-slot">Убрать текущего игрока</button>':'')+'</section><div class="cards-grid">'+choices.map(p=>'<button class="card-choice" data-pick="'+p.id+'">'+playerCard(p,true)+'</button>').join('')+'</div>';}
function cardsPage(){return header('Коллекция игроков')+'<section class="panel"><div class="panel-title">ВСЕ КАРТОЧКИ · '+team.allCards.length+'</div></section><div class="cards-grid">'+team.allCards.map(p=>'<button class="card-choice" data-player="'+p.id+'">'+playerCard(p)+'</button>').join('')+'</div>';}
function rinkVisual(){
 if(!match||!opponent)return '';
 const ev=match.events.length?match.events[match.events.length-1]:null;
 const faceoff=!!liveRuntime?.faceoff;
 const homeAttack=(liveRuntime?.owner||'home')==='home',res=ev?.result;
 const homeLines=matchHome?.lines.filter(l=>l.center&&l.leftWing&&l.rightWing&&l.defense1&&l.defense2)||[];
 const awayLines=opponent.lines.filter(l=>l.center&&l.leftWing&&l.rightWing&&l.defense1&&l.defense2);
 const homeLine=homeLines[(match.shift-1)%Math.max(1,homeLines.length)];
 const awayLine=awayLines[(match.shift-1)%Math.max(1,awayLines.length)];
 const h=homeLine?[homeLine.center,homeLine.leftWing,homeLine.rightWing,homeLine.defense1,homeLine.defense2]:[];
 const a=awayLine?[awayLine.center,awayLine.leftWing,awayLine.rightWing,awayLine.defense1,awayLine.defense2]:[];
 const initials=(p:PlayerCard)=>esc(p.name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase());
 const homeColor=matchHome?.club.primaryColor||'#168de0',awayColor=opponent.club.primaryColor||'#e46b48';
 const player=(p:PlayerCard|null|undefined,x:number,y:number,teamSide:'home'|'away',n:number,role:string,carrier=false)=>{
  const fill=teamSide==='home'?homeColor:awayColor;
  return '<g class="ice-player '+teamSide+' '+role+' p'+n+(carrier?' puck-carrier':'')+(res?.blocked&&res.blockerIndex===n-1&&ev?.side!==(teamSide)?' shot-blocker':'')+'" data-skater="'+teamSide+'-'+(n-1)+'" transform="translate('+x+' '+y+')"><circle cx="0" cy="0" r="19" fill="'+fill+'" stroke="#fff" stroke-width="3"/><circle cx="0" cy="0" r="15" fill="none" stroke="#ffffff77" stroke-width="1"/><text x="0" y="4" text-anchor="middle" font-size="11" font-weight="900" fill="#fff">'+(p?initials(p):String(n))+'</text></g>';
 };
 const homeY=faceoff?[294,235,385,255,365]:homeAttack?[360,320,320,410,410]:[430,390,390,470,470];
 const awayY=faceoff?[326,385,235,365,255]:homeAttack?[205,245,245,155,155]:[265,305,305,215,215];
 const homeXs=faceoff?[200,165,165,105,295]:[200,105,295,135,265],awayXs=faceoff?[200,235,235,295,295]:[200,105,295,135,265];
 const carrierIndex=res?.attackerIndex??0;
 const players=h.map((p,i)=>player(p,homeXs[i],homeY[i],'home',i+1,i<3?'forward':'defender',homeAttack&&i===carrierIndex)).join('')+
 a.map((p,i)=>player(p,awayXs[i],awayY[i],'away',i+1,i<3?'forward':'defender',!homeAttack&&i===carrierIndex)).join('');
 const homeGoalie=match.homeUseGoalie2?matchHome?.goalie2:matchHome?.goalie1;
 const awayGoalie=match.awayUseGoalie2?opponent.goalie2:opponent.goalie1;
 const goalie=(x:number,y:number,p:PlayerCard|null|undefined,teamSide:'home'|'away',defending=false)=>'<g class="ice-goalie '+teamSide+(defending?' defending-goalie':'')+'"><rect x="'+(x-23)+'" y="'+(y-22)+'" width="46" height="44" rx="12" fill="'+(teamSide==='home'?homeColor:awayColor)+'" stroke="#fff" stroke-width="3"/><text x="'+x+'" y="'+(y+5)+'" text-anchor="middle" font-size="13" font-weight="900" fill="#fff">ВР</text></g>';
 const shooterX= res?.attackerIndex===1?105:res?.attackerIndex===2?295:200;
 const shooterY=homeAttack?homeY[res?.attackerIndex??0]:awayY[res?.attackerIndex??0];
 const attackDir=homeAttack?-1:1;
 const supportIndex=carrierIndex===1?2:1;
 const supportX=homeXs[supportIndex],supportY=homeAttack?homeY[supportIndex]-22:awayY[supportIndex]+22;
 const targetX=res?.isShot?(res.shotX??200):supportX+(homeAttack?18:-18);
 const targetY=res?.isShot?(res.shotY??(homeAttack?62:558)):(homeAttack?Math.max(120,shooterY-34):Math.min(500,shooterY+34));
 const puckX=faceoff?200:targetX,puckY=faceoff?310:targetY;
 const bendX=(shooterX+supportX)/2+(homeAttack?34:-34),bendY=(shooterY+supportY)/2+attackDir*22;
 const finishBendX=(supportX+targetX)/2+(homeAttack?-28:28),finishBendY=(supportY+targetY)/2+attackDir*34;
 const puckPath=res?.isShot
  ? (res.isGoal
    ? 'M '+shooterX+' '+shooterY+' C '+(shooterX+(homeAttack?55:-55))+' '+(shooterY+attackDir*22)+' '+(homeAttack?250:150)+' '+(homeAttack?150:470)+' '+targetX+' '+targetY
    : 'M '+shooterX+' '+shooterY+' C '+(shooterX+(homeAttack?42:-42))+' '+(shooterY+attackDir*12)+' '+(homeAttack?176:224)+' '+(homeAttack?105:515)+' '+targetX+' '+targetY)
  : 'M '+shooterX+' '+shooterY+' Q '+bendX+' '+bendY+' '+supportX+' '+supportY+' Q '+finishBendX+' '+finishBendY+' '+targetX+' '+targetY;
 const resultClass=res?.isGoal?'goal-scored':res?.blocked?'shot-blocked':res?.goalieSaved?'shot-saved':res?.isShot?'shot-missed':'attack-stopped';

 const description=ev?ev.message:'';
 const progress=faceoff?0:(match.period-1)*5+match.shift;

 return '<div class="rink-scene live-simulation '+(faceoff?'faceoff ':'')+(homeAttack?'attack-home':'attack-away')+' '+resultClass+'">'+
 '<div class="rink-topline"><span id="live-possession-label">'+(faceoff?'🏒 ВБРАСЫВАНИЕ · НАЧАЛО МАТЧА':'🏒 LIVE · '+(homeAttack?esc(team.club.displayName):esc(opponent.name))+' АТАКУЕТ')+'</span><span>СМЕНА '+progress+'/15</span></div>'+
 '<svg class="ice-svg" viewBox="0 0 400 620" role="img" aria-label="Хоккейная площадка с движущимися игроками">'+
 '<defs><linearGradient id="iceFill" x1="0" x2="1" y1="0" y2="1"><stop offset="0" stop-color="#f4fbff"/><stop offset=".5" stop-color="#d9f0ff"/><stop offset="1" stop-color="#f4fbff"/></linearGradient><pattern id="iceGrain" width="28" height="28" patternUnits="userSpaceOnUse"><circle cx="4" cy="8" r=".7" fill="#8bbbd8" opacity=".25"/><circle cx="19" cy="22" r=".6" fill="#8bbbd8" opacity=".2"/></pattern></defs>'+
 '<rect x="8" y="8" width="384" height="604" rx="112" fill="url(#iceFill)" stroke="#fff" stroke-width="9"/><rect x="15" y="15" width="370" height="590" rx="104" fill="url(#iceGrain)" stroke="#6aa9d1" stroke-width="2"/>'+
 '<path d="M15 206 H385 M15 414 H385" stroke="#247bc1" stroke-width="5" opacity=".9"/><path d="M15 310 H385" stroke="#e34f64" stroke-width="4"/>'+
 '<circle cx="200" cy="310" r="66" fill="none" stroke="#d84f68" stroke-width="3"/><circle cx="200" cy="310" r="5" fill="#d84f68"/>'+
 '<g fill="none" stroke="#d84f68" stroke-width="2"><circle cx="85" cy="135" r="39"/><circle cx="315" cy="135" r="39"/><circle cx="85" cy="485" r="39"/><circle cx="315" cy="485" r="39"/></g>'+
 '<g fill="none" stroke="#277bc0" stroke-width="2"><path d="M15 90 Q200 90 385 90"/><path d="M15 530 Q200 530 385 530"/><path d="M125 15 V90 Q200 140 275 90 V15"/><path d="M125 605 V530 Q200 480 275 530 V605"/></g>'+
 '<g fill="#e9a2ad" opacity=".55"><path d="M145 38 Q200 10 255 38 L255 78 Q200 112 145 78Z"/><path d="M145 582 Q200 610 255 582 L255 542 Q200 508 145 542Z"/></g>'+
 '<g fill="none" stroke="#e14f65" stroke-width="5"><path d="M150 42 H250 V83 H150Z"/><path d="M150 578 H250 V537 H150Z"/></g>'+
 goalie(200,62,awayGoalie,'away',homeAttack)+goalie(200,558,homeGoalie,'home',!homeAttack)+players+
 '<defs><clipPath id="rinkInterior"><rect x="22" y="22" width="356" height="576" rx="94"/></clipPath></defs>'+
 '<g clip-path="url(#rinkInterior)">'+
 '<circle class="live-puck" data-live-puck cx="'+puckX+'" cy="'+puckY+'" r="7"/>'+
 '<circle class="puck-glow" data-puck-glow cx="'+puckX+'" cy="'+puckY+'" r="16"/></g>'+
 '</svg>'+
 (ev&&res?.isGoal?'<div class="rink-callout is-goal"><b>🥅 ГОООЛ!</b><span>'+esc(description)+'</span></div>':'')+
 '<div class="rink-legend"><span><i style="background:'+homeColor+'"></i>'+esc(team.club.displayName)+'</span><span><i style="background:'+awayColor+'"></i>'+esc(opponent.name)+'</span></div></div>';
}
function matchPage(){
 if(!match||!opponent){
  let ready=team.lines.some(l=>l.center&&l.leftWing&&l.rightWing&&l.defense1&&l.defense2)&&!!team.goalie1;
  return header('Подготовка к матчу')+'<section class="panel"><div class="panel-title">ВАША КОМАНДА</div><h2>'+esc(team.club.displayName)+'</h2><p>'+(ready?'Состав готов.':'Заполни хотя бы одно звено и выбери вратаря №1.')+' Сила: <b>'+teamPower(team).toFixed(1)+'</b></p></section><section class="panel"><div class="panel-title">СЛОЖНОСТЬ СОПЕРНИКА</div>'+(['EASY','MEDIUM','HARD'] as const).map(d=>'<button class="difficulty '+(difficulty===d?'selected':'')+'" data-difficulty="'+d+'">'+(d==='EASY'?'🟢 Лёгкая':d==='MEDIUM'?'🟡 Средняя':'🔴 Сложная')+(difficulty===d?' ✓':'')+'</button>').join('')+'<button class="primary start-match" data-action="start-match" '+(ready?'':'disabled')+'>🏒 Начать матч</button></section>';
 }
 const current=match!,rival=opponent!;
 const fin=current.finished,played=(current.period-1)*5+current.shift-1;
 const last=current.events.length?current.events[current.events.length-1]:null;
 const hGoalie=current.homeUseGoalie2?matchHome?.goalie2:matchHome?.goalie1;
 const aGoalie=current.awayUseGoalie2?rival.goalie2:rival.goalie1;
 const stamina=(v:number,m:number)=>Math.max(0,Math.min(100,Math.round(v/Math.max(.01,m)*100)));
 const homePct=stamina(current.homeUseGoalie2?current.homeGoalie2Stamina:current.homeGoalie1Stamina,current.homeUseGoalie2?current.homeGoalie2Max:current.homeGoalie1Max);
 const awayPct=stamina(current.awayUseGoalie2?current.awayGoalie2Stamina:current.awayGoalie1Stamina,current.awayUseGoalie2?current.awayGoalie2Max:current.awayGoalie1Max);
 const result=fin?(current.homeScore>current.awayScore?'ПОБЕДА':current.homeScore<current.awayScore?'ПОРАЖЕНИЕ':'НИЧЬЯ'):'МАТЧ В ПРОЦЕССЕ';
 return header('Матч')+
 '<section class="match-score-card"><div class="match-competition"><span>🏆 ТОВАРИЩЕСКИЙ МАТЧ</span><span class="live-dot">● LIVE</span></div><div class="scoreboard"><div class="team home"><span class="team-mark">'+esc(team.club.logo)+'</span><span class="team-name">'+esc(team.club.displayName)+'</span><b>'+current.homeScore+'</b></div><div class="center-score"><span>СЧЁТ</span><strong>:</strong><small>'+(fin?'ФИНАЛ':current.period+' ПЕРИОД · '+current.shift+' СМЕНА')+'</small></div><div class="team away"><b>'+current.awayScore+'</b><span class="team-name">'+esc(rival.name)+'</span><span class="team-mark">🥅</span></div></div><div class="match-clock"><span>ПЕРИОД '+current.period+' / 3</span><div class="period-dots">'+[1,2,3].map(n=>'<i class="'+(n<=current.period?'active':'')+'"></i>').join('')+'</div><span>СМЕНА '+current.shift+' / 5</span></div></section>'+
 '<section class="rink-wrap"><div class="rink-head"><span>ЛЕДОВАЯ АРЕНА · '+esc(team.stadium.name).toUpperCase()+'</span><span>🏒 5 НА 5</span></div>'+rinkVisual()+'</section>'+
 '<section class="ice-status"><div class="ice-status-player"><span class="status-crest" style="background:'+esc(matchHome?.club.primaryColor||'#168de0')+'">🧤</span><div><small>ВОРОТЧИК · ХОЗЯЕВА</small><b>'+esc(hGoalie?.name||'—')+'</b><div class="stamina-track"><i style="width:'+homePct+'%"></i></div></div><strong>'+homePct+'%</strong></div><div class="ice-status-player"><span class="status-crest away" style="background:'+esc(rival.club.primaryColor||'#e46b48')+'">🧤</span><div><small>ВОРОТЧИК · ГОСТИ</small><b>'+esc(aGoalie?.name||'—')+'</b><div class="stamina-track"><i style="width:'+awayPct+'%"></i></div></div><strong>'+awayPct+'%</strong></div></section>'+
 '<div class="below"><section class="panel controls"><div class="panel-title">УПРАВЛЕНИЕ МАТЧЕМ</div><p>'+(fin?'Матч окончен. Награда зачислена.':'Матч идёт непрерывно: игроки двигаются, разыгрывают шайбу и атакуют без пошаговых смен.')+'</p><button class="primary" data-action="pause-match" '+(fin?'disabled':'')+'>'+(liveRuntime?.paused?'▶ Продолжить матч':'Ⅱ Пауза матча')+'</button>'+(fin?'<button class="secondary" data-action="new-match">↻ Новый матч</button><button class="secondary" data-screen="office">🏠 В офис</button>':'')+'<div class="progress"><div style="width:'+(played/15*100)+'%"></div></div><small>ПРОГРЕСС · '+played+' / 15 СМЕН</small></section><section class="panel"><div class="panel-title">ХОД МАТЧА <span class="live-dot">● LIVE</span></div><div class="events">'+(match!.log.slice(-12).reverse().map((x,i)=>'<div class="event '+(i===0?'latest':'')+'"><i></i><span>'+esc(x)+'</span></div>').join('')||'<p>Матч готов.</p>')+'</div></section></div>';
}
function wardrobePage(){let p=team.allCards.find(x=>x.id===selectedId)||team.allCards[0];if(!p)return header('Гардероб');selectedId=p.id;let slots=p.isGoalie?['Коньки','Щитки','Ловушка','Клюшка','Шлем']:['Коньки','Клюшка','Джерси','Шлем','Шорты'];let gear=team.equipment[p.id]||[];return header('Гардероб')+'<section class="panel"><div class="wallet-row"><div class="wallet"><small>БЮДЖЕТ</small><b>💵 '+money(team.economy.dollars)+'</b></div><div class="wallet gold"><small>ЗОЛОТЫЕ ШАЙБЫ</small><b>🟡 '+team.economy.goldPucks+'</b></div></div><div class="panel-title">ВЫБЕРИ ИГРОКА</div><div class="player-strip">'+team.allCards.map(x=>'<button class="player-chip '+(x.id===p.id?'active':'')+'" data-select-player="'+x.id+'">'+(x.isGoalie?'🥅':'🏒')+' '+esc(x.name)+'</button>').join('')+'</div><div class="selected-player">'+playerCard(p,true)+'</div><div class="tabs"><button class="tab" data-tab="inventory">🎒 Инвентарь</button><button class="tab" data-tab="shop">🛒 Магазин</button></div><div id="wardrobe-content">'+slots.map(s=>{let x=gear.find(g=>g.slot===s);return '<div class="gear-row"><div><b>'+s+'</b><small>'+(x?esc(x.name)+' · '+x.rarity:'Пусто')+'</small></div>'+(x?'<button class="secondary small" data-unequip="'+s+'">Снять</button>':'')+'</div>';}).join('')+'<h3>Предметы в инвентаре</h3><p>Выбери вкладку «Магазин», чтобы купить экипировку.</p></div></section>';}
function heroSetupPage(){const roles:HeroRole[]=['LW','C','RW','LD','RD','G'];return header('Создание героя',false)+'<section class="hero-creation-intro"><span class="hero-kicker"><i></i> YOUR CAREER STARTS HERE</span><h2>ВЫБЕРИ СВОЮ ПОЗИЦИЮ</h2><p>Это твой главный персонаж. Его навыки, экипировка и трофеи будут развиваться вместе с карьерой.</p><label class="hero-name-field">ИМЯ ИГРОКА<input id="hero-name" maxlength="22" placeholder="Например, Алексей Морозов"></label></section><div class="hero-role-grid">'+roles.map(role=>'<button class="hero-role-card '+(role==='G'?'goalie-role':'')+'" data-create-hero="'+role+'"><span class="hero-role-number">'+(role==='G'?'06':'0'+(roles.indexOf(role)+1))+'</span><span class="hero-role-icon">'+(role==='G'?'🧤':role==='LD'||role==='RD'?'🛡️':'🏒')+'</span><b>'+heroRoleShort[role]+'</b><small>'+heroRoleNames[role]+'</small><i>ВЫБРАТЬ →</i></button>').join('')+'</div><p class="hero-creation-note">ПОЗИЦИЮ МОЖНО БУДЕТ ИЗМЕНИТЬ ПОЗЖЕ В НАСТРОЙКАХ КАРЬЕРЫ</p>';}
function heroRoomPage(){if(!hero)return heroSetupPage();const gearSet=hero.gear;const goalie=hero.role==='G';const points=hero.skillPoints??5;const slots=heroGearSlots(hero.role);const gearIcons=goalie?['⛑️','🦵','🧤','🥅','🏒','🦺','⛸️']:['⛑️','🦺','🧤','🏒','⛸️','👕','🩳'];const statRows:[string,number][]=[['СКОРОСТЬ',hero.stats.speed],['ЛОВКОСТЬ',hero.stats.agility],['СИЛА',hero.stats.strength],['ВЫНОСЛИВОСТЬ',hero.stats.stamina],...(goalie?[['РЕАКЦИЯ',hero.stats.reaction] as [string,number]]:[])];return header('Комната героя')+'<section class="hero-room-heading"><div><small>ЛИЧНАЯ РАЗДЕВАЛКА · CAREER HQ</small><h2>'+esc(hero.name)+'</h2><span>'+heroRoleNames[hero.role]+' · УРОВЕНЬ '+hero.level+'</span></div><div class="hero-level-badge"><b>'+hero.level+'</b><small>LVL</small></div></section><section class="hero-room"><div class="hero-room-topline"><span>ЭКИПИРОВКА</span><span>КОМПЛЕКТ № 01</span></div><div class="hero-equipment-layout"><div class="hero-gear-column">'+slots.slice(0,Math.ceil(slots.length/2)).map((s,i)=>'<div class="hero-gear-slot"><span>'+gearIcons[i]+'</span><div><small>'+s.toUpperCase()+'</small><b>'+esc(gearSet[i]||'Не экипировано')+'</b></div><i>✓</i></div>').join('')+'</div><div class="hero-player-stage '+(goalie?'is-goalie':'')+'"><div class="hero-stage-glow"></div><div class="hero-man"><div class="hero-stick"></div><div class="hero-helmet"><i></i></div><div class="hero-neck"></div><div class="hero-shoulders"></div><div class="hero-body"><b>PUCK IT!</b><small>'+heroRoleShort[hero.role]+'</small></div><div class="hero-arm left"></div><div class="hero-arm right"></div><div class="hero-gloves"><i></i></div><div class="hero-pants"></div><div class="hero-leg left"></div><div class="hero-leg right"></div><div class="hero-skate left"></div><div class="hero-skate right"></div>'+(goalie?'<div class="hero-goalie-pad left"></div><div class="hero-goalie-pad right"></div><div class="hero-catcher"></div><div class="hero-blocker"></div>':'')+'</div><div class="hero-stage-caption">'+(goalie?'ВРАТАРСКИЙ КОМПЛЕКТ':'ИГРОВОЙ КОМПЛЕКТ')+'</div></div><div class="hero-gear-column">'+slots.slice(Math.ceil(slots.length/2)).map((s,i)=>{const n=i+Math.ceil(slots.length/2);return '<div class="hero-gear-slot"><span>'+gearIcons[n]+'</span><div><small>'+s.toUpperCase()+'</small><b>'+esc(gearSet[n]||'Не экипировано')+'</b></div><i>✓</i></div>';}).join('')+'</div></div><div class="hero-room-bottom"><span>ЭКИПИРОВКА ГЕРОЯ</span><span>ВСЕ ПРЕДМЕТЫ · '+slots.length+'</span></div></section><section class="hero-stats-panel"><div class="hero-panel-title"><span>ХАРАКТЕРИСТИКИ</span><b>ОБЩИЙ РЕЙТИНГ '+Math.round(Object.values(hero.stats).slice(0,goalie?5:4).reduce((a,b)=>a+b,0)/(goalie?5:4))+'</b></div><div class="hero-skill-points"><span>НЕРАСПРЕДЕЛЁННЫЕ ОЧКИ</span><b>'+points+'</b></div><div class="hero-stats-grid">'+statRows.map(([label,value])=>'<div class="hero-stat"><div><small>'+label+'</small><b>'+value+'</b></div><span><i style="width:'+Math.max(0,Math.min(100,Number(value)))+'%"></i></span><div class="hero-stat-actions"><small>+1 ЗА 1 ОЧКО</small><button data-hero-upgrade="'+({СКОРОСТЬ:'speed',ЛОВКОСТЬ:'agility',СИЛА:'strength',ВЫНОСЛИВОСТЬ:'stamina',РЕАКЦИЯ:'reaction'} as Record<string,string>)[label]+'" '+(points<1||value>=99?'disabled':'')+'>＋</button></div></div>').join('')+'</div><p class="hero-skill-note">Каждое очко повышает выбранный навык на 1 пункт. Максимум — 99.</p><div class="hero-xp"><span>ОПЫТ</span><b>'+hero.xp+' / 100 XP</b><i><em style="width:'+Math.min(100,hero.xp)+'%"></em></i></div></section><section class="hero-trophy-room"><div class="hero-panel-title"><span>ВИТРИНА ТРОФЕЕВ</span><b>'+hero.trophies.length+' НАГРАД</b></div><div class="hero-trophy-shelf">'+(hero.trophies.length?hero.trophies.map(t=>'<div class="hero-trophy"><b>🏆</b><small>'+esc(t)+'</small></div>').join(''):'<div class="hero-trophy empty"><b>🏆</b><small>ПЕРВЫЙ КУБОК</small><i>Здесь появится твоя первая победа</i></div><div class="hero-trophy empty"><b>🥇</b><small>ЗОЛОТЫЕ МЕДАЛИ</small><i>Награды за достижения</i></div><div class="hero-trophy empty"><b>⭐</b><small>ОСОБЫЕ НАГРАДЫ</small><i>За личные рекорды</i></div>')+'</div></section><button class="secondary hero-back-button" data-screen="office">← ВЕРНУТЬСЯ В ОФИС</button>';}
function clubPage(){return header('Мой клуб')+'<section class="panel"><div class="panel-title">ПРОФИЛЬ КЛУБА</div><label>Название клуба<input id="club-name" maxlength="24" value="'+esc(team.club.displayName)+'"></label><label>Эмблема<input id="club-logo" maxlength="4" value="'+esc(team.club.logo)+'"></label><label>Домашняя форма<input id="home-jersey" value="'+esc(team.club.homeJersey)+'"></label><label>Гостевая форма<input id="away-jersey" value="'+esc(team.club.awayJersey)+'"></label><button class="primary" data-action="save-club">Сохранить клуб</button></section>';}
function stadiumPage(){let s=team.stadium;let economy=team.economy;let items:[keyof Team['stadium'],string][]=[['capacityLevel','Вместимость'],['lightingLevel','Освещение'],['scoreboardLevel','Табло'],['lockerRoomLevel','Раздевалки'],['iceLevel','Качество льда'],['vipLevel','VIP-зона']];return header('Стадион')+'<section class="panel"><div class="panel-title">🏟️ '+esc(s.name)+'</div><h2>'+(500+(s.capacityLevel-1)*250)+' мест</h2><p>Доход за домашний матч: 💵 '+(100+s.capacityLevel*35+s.vipLevel*50+s.lightingLevel*15)+'</p><p>Бюджет клуба: 💵 '+money(economy.dollars)+'</p><label>Название стадиона<input id="stadium-name" value="'+esc(s.name)+'"></label><button class="secondary" data-action="save-stadium">Сохранить название</button></section>'+items.map(([k,label])=>'<section class="panel upgrade-row"><div><b>'+label+'</b><small>Уровень '+s[k]+' / 5 · улучшение: 💵 '+Number(s[k])*500+'</small></div><button class="secondary small" data-upgrade="'+k+'" '+(Number(s[k])>=5||economy.dollars<Number(s[k])*500?'disabled':'')+'>Улучшить</button></section>').join('');}
function playoffPage(){const games=[['Четвертьфинал','Матч 1','Северные Волки','Ледяные Ястребы','4 : 2','Завершён'],['Четвертьфинал','Матч 2','Полярные Медведи','Стальные Лисы','1 : 1','Идёт'],['Четвертьфинал','Матч 3','Красные Молнии','Арктические Львы','— : —','Не сыгран'],['Четвертьфинал','Матч 4','Белые Тигры','Шторм','— : —','Не сыгран'],['Полуфинал','Матч 5','Победитель М1','Победитель М2','— : —','Не сыгран'],['Полуфинал','Матч 6','Победитель М3','Победитель М4','— : —','Не сыгран'],['Матч за 3-е место','Бронзовый матч','Проигравший М5','Проигравший М6','— : —','Не сыгран'],['Финал','Золотой матч','Победитель М5','Победитель М6','— : —','Не сыгран']];let html=header('Мини-турнир')+'<section class="panel"><div class="panel-title">ПЛЕЙ-ОФФ · 8 КОМАНД</div><p>Четвертьфиналы → полуфиналы → матч за третье место и финал.</p></section>';['Четвертьфинал','Полуфинал','Матч за 3-е место','Финал'].forEach(round=>{html+='<div class="section-heading">'+round.toUpperCase()+'</div>';games.filter(g=>g[0]===round).forEach(g=>{html+='<section class="panel bracket-match"><div class="bracket-head"><small>'+g[1]+'</small><span>'+g[5]+'</span></div><div><b>🏒 '+g[2]+'</b><strong>'+g[4]+'</strong></div><div><b>🏒 '+g[3]+'</b></div></section>';});});return html+'<section class="panel"><p>Победитель финала — золото · проигравший — серебро · победитель матча за 3-е место — бронза.</p><small>Сетка пока демонстрационная, подключение результатов к игровому календарю — отдельный этап.</small></section>';}
function standingsPage(){type Row={name:string;g:number;w:number;otw:number;otl:number;l:number;gf:number;ga:number;rw:number;row:number;h2h:number;diff:number;pts:number};const raw:[string,number,number,number,number,number,number,number,number,number,number][]=[['Северные Волки',8,6,1,1,0,31,15,6,7,4],['Ледяные Ястребы',8,6,0,1,1,28,16,6,6,3],['Полярные Медведи',8,5,1,0,2,27,18,5,6,2],['Стальные Лисы',8,4,2,1,1,25,20,4,6,3],['Красные Молнии',8,4,1,1,2,24,21,4,5,2],['Арктические Львы',8,3,2,0,3,22,23,3,5,1],['Белые Тигры',8,3,0,2,3,20,22,3,3,2],['Шторм',8,2,1,2,3,19,25,2,3,1],['Ледяные Драконы',8,1,1,1,5,16,27,1,2,0],['Снежные Барсы',8,0,1,1,6,12,37,0,1,0]];const rows:Row[]=raw.map(r=>({name:r[0],g:r[1],w:r[2],otw:r[3],otl:r[4],l:r[5],gf:r[6],ga:r[7],rw:r[8],row:r[9],h2h:r[10],diff:r[6]-r[7],pts:r[2]*2+r[3]*2+r[4]})).sort((a,b)=>a.g-b.g||b.rw-a.rw||b.row-a.row||b.w-a.w||b.h2h-a.h2h||b.diff-a.diff);let html=header('Турнирная таблица')+'<section class="panel"><div class="panel-title">РЕГУЛЯРНЫЙ ЧЕМПИОНАТ · 10 КОМАНД</div><p>2 очка за победу · 1 очко за поражение в овертайме или буллитах.</p><div class="table-scroll"><table class="standings-table"><thead><tr><th>№</th><th>Команда</th><th>И</th><th>В</th><th>ВО</th><th>ПО</th><th>П</th><th>ШЗ</th><th>ШП</th><th>РШ</th><th>О</th></tr></thead><tbody>';rows.forEach((r,i)=>{html+='<tr><td>'+(i+1)+'</td><td>'+r.name+'</td><td>'+r.g+'</td><td>'+r.w+'</td><td>'+r.otw+'</td><td>'+r.otl+'</td><td>'+r.l+'</td><td>'+r.gf+'</td><td>'+r.ga+'</td><td>'+(r.diff>0?'+'+r.diff:r.diff)+'</td><td><b>'+r.pts+'</b></td></tr>';});return html+'</tbody></table></div></section><section class="panel"><b>Тай-брейк</b><p>Меньше игр → больше RW → ROW → общие победы → личные встречи → разница шайб.</p><small>Демонстрационные данные, как в Android-экране.</small></section>';}
function render(){let pages:Record<Screen,()=>string>={heroSetup:heroSetupPage,heroRoom:heroRoomPage,office,team:teamPage,cards:cardsPage,match:matchPage,wardrobe:wardrobePage,club:clubPage,stadium:stadiumPage,playoff:playoffPage,standings:standingsPage,settings:()=>header('Настройки')+'<section class="panel"><p>Сохранение хранится в этом браузере.</p><button class="secondary" data-action="export">Экспортировать сохранение</button><button class="secondary" data-action="reset">Сбросить прогресс</button></section>',picker:pickerPage,player:()=>{let p=team.allCards.find(x=>x.id===selectedId);return p?header('Карточка игрока')+playerCard(p):header('Карточка игрока');}};let app=$<HTMLDivElement>('#app');if(app)app.innerHTML='<main class="shell">'+pages[screen]()+(notice?'<div class="toast">'+esc(notice)+'</div>':'')+'</main>';}
function stopAuto(){if(autoTimer!==undefined){clearTimeout(autoTimer);autoTimer=undefined;}}
