function showWardrobeTab(tab:'inventory'|'shop'){let p=team.allCards.find(x=>x.id===selectedId)||team.allCards[0];if(!p)return;let slots=p.isGoalie?['Коньки','Щитки','Ловушка','Клюшка','Шлем']:['Коньки','Клюшка','Джерси','Шлем','Шорты'];let cat=equipmentCatalog(slots),gear=team.equipment[p.id]||[],equipped=Object.values(team.equipment).flat().map(x=>x.id),owned=new Set([...team.ownedEquipmentIds,...equipped]);let el=$<HTMLDivElement>('#wardrobe-content');if(!el)return;if(tab==='inventory'){el.innerHTML=slots.map(s=>{let x=gear.find(g=>g.slot===s);return '<div class="gear-row"><div><b>'+s+'</b><small>'+(x?esc(x.name):'Пусто')+'</small></div>'+(x?'<button class="secondary small" data-unequip="'+s+'">Снять</button>':'')+'</div>';}).join('')+'<h3>Предметы в инвентаре</h3>'+cat.filter(x=>owned.has(x.id)&&!equipped.includes(x.id)).map(x=>'<div class="gear-card"><div><b>'+esc(x.name)+'</b><small>'+x.rarity+' · +'+x.speedBonus+' к скорости</small></div><button class="secondary small" data-wear="'+x.id+'">Надеть</button></div>').join('');}else{el.innerHTML='<p>Покупка отправляет предмет в инвентарь. Подтверждение обязательно.</p>'+cat.map(x=>'<div class="gear-card"><div><b>'+esc(x.name)+'</b><small>'+x.slot+' · '+x.rarity+' · '+(x.goldPuckPrice?'🟡 '+x.goldPuckPrice:'💵 '+x.dollarPrice)+'</small></div>'+(owned.has(x.id)?'<b>УЖЕ ЕСТЬ ✓</b>':'<button class="secondary small" data-buy="'+x.id+'">Купить</button>')+'</div>').join('');}}
document.addEventListener('click',e=>{let t=e.target as HTMLElement;let nav=t.closest<HTMLElement>('[data-screen]');if(nav){stopAuto();stopLiveLoop();screen=nav.dataset.screen as Screen;if(screen==='match'&&match?.finished){match=null;matchHome=null;opponent=null;}if(screen==='wardrobe')selectedId=team.allCards[0]?.id||null;render();return;}let act=t.closest<HTMLElement>('[data-action]');if(act){let a=act.dataset.action;if(a==='back'){stopAuto();stopLiveLoop();screen=screen==='picker'?'team':screen==='player'?'cards':'office';slot=null;render();}if(a==='autofill'){team=autoFillRoster(team);save();toast('Состав заполнен.');}if(a==='remove-slot'&&slot){if(slot.kind==='goalie'){if(slot.number===1)team.goalie1=null;else team.goalie2=null;}else team.lines[slot.line][slot.field]=null;slot=null;screen='team';save();render();}if(a==='start-match')startMatch();if(a==='next-shift')nextShift();if(a==='pause-match'){if(liveRuntime){liveRuntime.paused=!liveRuntime.paused;render();}}if(a==='auto-match'){if(liveRuntime){liveRuntime.paused=!liveRuntime.paused;render();}}if(a==='stop-auto'){if(liveRuntime){liveRuntime.paused=true;render();}}if(a==='new-match'){stopAuto();stopLiveLoop();match=null;matchHome=null;opponent=null;render();}if(a==='save-stadium'){team.stadium={...team.stadium,name:$<HTMLInputElement>('#stadium-name')?.value.trim()||'Ледовая арена'};save();toast('Стадион сохранён.');}if(a==='save-club'){team.name=$<HTMLInputElement>('#club-name')?.value.trim()||'Моя команда';team.club={...team.club,displayName:team.name,logo:$<HTMLInputElement>('#club-logo')?.value.trim()||'🏒',homeJersey:$<HTMLInputElement>('#home-jersey')?.value.trim()||'Домашняя',awayJersey:$<HTMLInputElement>('#away-jersey')?.value.trim()||'Гостевая'};save();toast('Клуб сохранён.');}if(a==='export'){let u=URL.createObjectURL(new Blob([JSON.stringify(team,null,2)],{type:'application/json'}));let link=document.createElement('a');link.href=u;link.download='hockey-manager-save.json';link.click();URL.revokeObjectURL(u);}if(a==='reset'&&confirm('Удалить сохранение?')){stopLiveLoop();team=createTeam();save();hero=null;localStorage.removeItem(HERO_KEY);match=null;matchHome=null;opponent=null;screen='heroSetup';render();}return;}
let create=t.closest<HTMLElement>('[data-create-hero]');if(create){const role=create.dataset.createHero as HeroRole;hero=makeHero(role,$<HTMLInputElement>('#hero-name')?.value||'');saveHero(hero);screen='office';render();return;}let sl=t.closest<HTMLElement>('[data-slot]');if(sl){slot=JSON.parse(decodeURIComponent(sl.dataset.slot!));screen='picker';render();return;}let pick=t.closest<HTMLElement>('[data-pick]');if(pick&&slot){let p=team.allCards.find(x=>x.id===pick.dataset.pick);if(p){if(slot.kind==='goalie'){if(slot.number===1)team.goalie1=p;else team.goalie2=p;}else team.lines[slot.line][slot.field]=p;slot=null;screen='team';save();render();}return;}let d=t.closest<HTMLElement>('[data-difficulty]');if(d){difficulty=d.dataset.difficulty as MatchDifficulty;render();return;}let pl=t.closest<HTMLElement>('[data-player]');if(pl){selectedId=pl.dataset.player!;screen='player';render();return;}let sp=t.closest<HTMLElement>('[data-select-player]');if(sp){selectedId=sp.dataset.selectPlayer!;render();return;}let tab=t.closest<HTMLElement>('[data-tab]');if(tab){showWardrobeTab(tab.dataset.tab as 'inventory'|'shop');return;}let buy=t.closest<HTMLElement>('[data-buy]');if(buy){let p=team.allCards.find(x=>x.id===selectedId);if(!p)return;let slots=p.isGoalie?['Коньки','Щитки','Ловушка','Клюшка','Шлем']:['Коньки','Клюшка','Джерси','Шлем','Шорты'];let x=equipmentCatalog(slots).find(y=>y.id===buy.dataset.buy);if(!x)return;if(x.goldPuckPrice?team.economy.goldPucks<x.goldPuckPrice:team.economy.dollars<x.dollarPrice){toast('Недостаточно средств.');return;}if(!confirm('Купить «'+x.name+'»?'))return;team.economy=x.goldPuckPrice?{...team.economy,goldPucks:team.economy.goldPucks-x.goldPuckPrice}:{...team.economy,dollars:team.economy.dollars-x.dollarPrice};team.ownedEquipmentIds.push(x.id);save();showWardrobeTab('shop');renderWallet();return;}let wear=t.closest<HTMLElement>('[data-wear]');if(wear){let p=team.allCards.find(x=>x.id===selectedId);if(!p)return;let slots=p.isGoalie?['Коньки','Щитки','Ловушка','Клюшка','Шлем']:['Коньки','Клюшка','Джерси','Шлем','Шорты'];let x=equipmentCatalog(slots).find(y=>y.id===wear.dataset.wear);if(x){team.equipment[p.id]=[...(team.equipment[p.id]||[]).filter(y=>y.slot!==x.slot),x];save();showWardrobeTab('inventory');}return;}let un=t.closest<HTMLElement>('[data-unequip]');if(un){let p=team.allCards.find(x=>x.id===selectedId);if(p){team.equipment[p.id]=(team.equipment[p.id]||[]).filter(x=>x.slot!==un.dataset.unequip);save();showWardrobeTab('inventory');}return;}let heroUp=t.closest<HTMLElement>('[data-hero-upgrade]');if(heroUp&&hero){const key=heroUp.dataset.heroUpgrade as keyof HeroProfile['stats'];const points=hero.skillPoints??5;if(points<1){toast('Нет свободных очков навыков.');return;}if(hero.stats[key]>=99){toast('Навык уже достиг максимума.');return;}hero={...hero,skillPoints:points-1,stats:{...hero.stats,[key]:hero.stats[key]+1}};saveHero(hero);render();return;}let up=t.closest<HTMLElement>('[data-upgrade]');if(up){let k=up.dataset.upgrade as keyof Team['stadium'];let level=Number(team.stadium[k]),cost=level*500;if(level>=5){toast('Достигнут максимальный уровень.');return;}if(team.economy.dollars<cost){toast('Недостаточно денег клуба.');return;}team.stadium={...team.stadium,[k]:level+1};team.economy={...team.economy,dollars:team.economy.dollars-cost};save();render();}});
function renderWallet(){let w=$<HTMLDivElement>('.wallet-row');if(w)w.innerHTML='<div class="wallet"><small>БЮДЖЕТ</small><b>💵 '+money(team.economy.dollars)+'</b></div><div class="wallet gold"><small>ЗОЛОТЫЕ ШАЙБЫ</small><b>🟡 '+team.economy.goldPucks+'</b></div>';}
render();
